def check_K(tup, k):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    ensures  r == (exists i in [0, len(tup)) . tup[i] == k)
    """
    if not (_t_ints(tup, 1)):
        raise TypeError('check_K: `tup` must be a list of integers; nothing was proved for anything else')
    if not (_t_ints(k, 0)):
        raise TypeError('check_K: `k` must be an integer; nothing was proved for anything else')
    tup = _t_tuple(tup)
    _t_result = _t_core(tup, k)
    return _t_result

def _t_core(tup, k):
    r = False
    i = 0
    # invariant: 0 <= i
    # invariant: i <= len(tup)
    # invariant: r ==> (exists j in [0, i) . tup[j] == k)
    # invariant: not r ==> (forall j in [0, i) . tup[j] != k)
    # decreases: len(tup) - i
    while ((i < len(tup)) and (not r)):
        if (tup[i] == k):
            r = True
        i = (i + 1)
    return r

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

